// src/components/IncomeCategory.js
import React from "react";
import { useNavigate } from "react-router-dom";
import "./IncomeCategory.css";
import { FaDollarSign, FaBriefcase, FaUserTie, FaHandshake, FaMoneyBillWave, FaLayerGroup } from "react-icons/fa";

const categoriesData = [
  { name: "Fixed Income", icon: <FaDollarSign color="#4CAF50" /> },
  { name: "Variable Income", icon: <FaBriefcase color="#2196F3" /> },
  { name: "Freelancer/Gig", icon: <FaUserTie color="#FF9800" /> },
  { name: "Business Owner", icon: <FaHandshake color="#9C27B0" /> },
  { name: "No Income", icon: <FaMoneyBillWave color="#F44336" /> },
  { name: "Multiple Sources", icon: <FaLayerGroup color="#3F51B5" /> },
];

function IncomeCategory({ updateData }) {
  const navigate = useNavigate();

  const handleSelect = (category) => {
    updateData({ category: [category] });
    navigate("/questionnaire");
  };

  return (
    <div className="income-container">
      <h2 className="income-title">Select Your Income Category</h2>
      <div className="income-grid">
        {categoriesData.map(cat => (
          <div key={cat.name} className="income-card" onClick={() => handleSelect(cat.name)}>
            <div className="income-icon">{cat.icon}</div>
            <div className="income-name">{cat.name}</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default IncomeCategory;
